def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'

    opp_def = sum(1 for _, o in history if o == 'D')
    my_def = sum(1 for m, _ in history if m == 'D')
    last_my, last_opp = history[-1]

    # Probe at round 20 (n=19) if no defections yet
    if n == 19 and opp_def == 0 and my_def == 0:
        return 'D'

    # Determine if opponent is forgiving based on probe response
    is_forgiving = False
    if n > 20 and my_def >= 1:
        first_my_def_idx = -1
        for i in range(n):
            if history[i][0] == 'D':
                first_my_def_idx = i
                break
        if first_my_def_idx == 19:
            if history[19][1] == 'C' and history[20][1] == 'C':
                is_forgiving = True

    # Endgame exploitation for forgiving opponents
    if is_forgiving and opp_def <= 2:
        recent_opp_def = sum(1 for _, o in history[-3:] if o == 'D')
        if recent_opp_def == 0:
            if (n >= 74 and n % 2 == 0) or n == 99:
                return 'D'
        else:
            is_forgiving = False

    # Always defect on the last round
    if n == 99:
        return 'D'

    # Base TFT with forgiveness
    if n < 10:
        if last_opp == 'D':
            return 'D'
        return 'C'

    if last_opp == 'C':
        return 'C'
    else:
        if opp_def <= max(1, n // 10):
            return 'C'
        if opp_def > n * 0.3:
            return 'D'
        if last_my == 'D' and n >= 2 and history[-2][1] == 'D':
            return 'C'
        return 'D'
